	private static FilteredBindingSetAssignmentJoinIteration.DirectCondition directCondition(ValueExpr condition,
			QueryEvaluationContext context, boolean strict) {
		if (!(condition instanceof Compare)) {
			return null;
		}
		Compare compare = (Compare) condition;
		Function<BindingSet, Value> left = directValue(compare.getLeftArg(), context);
		Function<BindingSet, Value> right = directValue(compare.getRightArg(), context);
		if (left == null || right == null) {
			return null;
		}
		Compare.CompareOp operator = compare.getOperator();
		return bindings -> {
			Value leftValue = left.apply(bindings);
			Value rightValue = right.apply(bindings);
			if (leftValue == null || rightValue == null) {
				return false;
			}
			return QueryEvaluationUtil.compare(leftValue, rightValue, operator, strict);
		};
	}

	private static Function<BindingSet, Value> directValue(ValueExpr valueExpr, QueryEvaluationContext context) {
		if (valueExpr instanceof Var) {
			Var var = (Var) valueExpr;
			if (var.hasValue()) {
				Value value = var.getValue();
				return ignored -> value;
			}
			return context.getValue(var.getName());
		}
		if (valueExpr instanceof ValueConstant) {
			Value value = ((ValueConstant) valueExpr).getValue();
			return ignored -> value;
		}
		return null;
	}

	private static boolean containsAny(Set<String> left, Set<String> right) {
		for (String name : left) {
			if (right.contains(name)) {
				return true;
			}
		}
		return false;
	}

	private static List<BindingSet> bindingRows(BindingSetAssignment assignment) {
		List<BindingSet> rows = new ArrayList<>();
		if (assignment.getBindingSets() == null) {
			return rows;
		}
		for (BindingSet row : assignment.getBindingSets()) {
			rows.add(row);
		}
		return List.copyOf(rows);
	}

	private static Map<String, FilteredBindingSetAssignmentJoinIteration.BindingNameAccess> bindingNameAccess(
			BindingSetAssignment assignment,
			QueryEvaluationContext context) {
		Map<String, FilteredBindingSetAssignmentJoinIteration.BindingNameAccess> bindingNamesByName = new HashMap<>(
				assignment.getBindingNames().size() * 2);
		for (String bindingName : assignment.getBindingNames()) {
			bindingNamesByName.put(bindingName,
					new FilteredBindingSetAssignmentJoinIteration.BindingNameAccess(bindingName, context));
		}
		return Map.copyOf(bindingNamesByName);
	}

